package com.ptms.service;import org.springframework.stereotype.Service;import java.util.*;@Service public class TicketCombinationService{private final SettingsService settings;public TicketCombinationService(SettingsService settings){this.settings=settings;}public List<List<Integer>> combinationsFor(int h){if(h<=0)return List.of(List.of());List<Integer>a=Arrays.stream(settings.get().ticketTypes().split(",")).map(String::trim).map(Integer::parseInt).sorted(Comparator.reverseOrder()).toList();List<List<Integer>>r=new ArrayList<>();search(h,0,new ArrayList<>(),r,a);int m=r.stream().mapToInt(List::size).min().orElse(0);return r.stream().filter(x->x.size()==m).distinct().limit(5).toList();}private void search(int rem,int start,List<Integer>cur,List<List<Integer>>out,List<Integer>a){if(rem==0){out.add(List.copyOf(cur));return;}for(int i=start;i<a.size();i++){int v=a.get(i);if(v>rem)continue;cur.add(v);search(rem-v,i,cur,out,a);cur.remove(cur.size()-1);}}}
